(async()=>{try{const r=await fetch('/data/iris-model.json');if(!r.ok)throw Error('Model unavailable');const m=await r.json();const inputs=[0,1,2,3].map(i=>document.querySelector('#f'+i));function predict(){const x=inputs.map((el,i)=>{document.querySelector('#v'+i).textContent=(+el.value).toFixed(1)+' cm';return (+el.value-m.mean[i])/m.scale[i]});const z=m.coef.map((row,k)=>row.reduce((v,c,i)=>v+c*x[i],m.intercept[k]));const max=Math.max(...z),exp=z.map(v=>Math.exp(v-max)),total=exp.reduce((a,b)=>a+b,0),p=exp.map(v=>v/total);const winner=p.indexOf(Math.max(...p));document.querySelector('#prediction').textContent='Iris '+m.classes[winner];document.querySelector('#probabilities').innerHTML=m.classes.map((c,i)=>`<div class="prob-row">${c}<b>${(p[i]*100).toFixed(1)}%</b><progress aria-label="${c} probability" max="1" value="${p[i]}"></progress></div>`).join('')}inputs.forEach(el=>el.addEventListener('input',predict));for(const b of document.querySelectorAll('[data-example]'))b.addEventListener('click',()=>{m.examples[+b.dataset.example].forEach((v,i)=>inputs[i].value=v);predict()});document.querySelector('#accuracy').textContent=(m.accuracy*100).toFixed(1)+'% test accuracy ('+Math.round(m.accuracy*m.test_count)+' / '+m.test_count+' correct).';document.querySelector('#matrix').innerHTML='<table class="lab-table"><thead><tr><th>Actual / predicted</th>'+m.classes.map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+m.confusion.map((row,i)=>'<tr><th>'+m.classes[i]+'</th>'+row.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table>';document.querySelector('#lab-status').textContent='Model loaded · Inference runs locally in your browser';predict()}catch(e){document.querySelector('#lab-status').textContent='Could not load the model. Please reload to try again.'}})();
